  let shade=null, reader=null, card=null;
  function close(){card?.remove();card=null;shade?.remove();reader?.remove();shade=reader=null;document.documentElement.classList.remove('kena-article-open');root.querySelectorAll('.shastra-name.is-active').forEach(b=>{b.classList.remove('is-active');b.setAttribute('aria-pressed','false');});}
  function source(article,n){const s=article.notes[n-1];if(!s)return;card?.remove();card=document.createElement('aside');card.className='itihasa-source-card';card.innerHTML=`<button class="itihasa-source-close" type="button" aria-label="Close">×</button><div class="itihasa-source-num">Source ${n}</div><strong>${esc(s.title)}</strong><p>${esc(s.detail)}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">Open source ↗</a>`:''}`;document.body.append(card);card.querySelector('.itihasa-source-close')?.addEventListener('click',()=>{card?.remove();card=null;});}
  function notes(article){return `<section class="kena-section kena-references" id="itihasa-notes"><h2>Sources</h2><ol>${article.notes.map((s,i)=>`<li><button class="itihasa-note-link" type="button" data-note="${i+1}">${i+1}</button> <b>${esc(s.title)}</b><br><span>${esc(s.detail)}</span></li>`).join('')}</ol></section>`;}
  function infobox(a){return `<aside class="kena-infobox"><div class="kena-infobox-title">${esc(a.title)}</div><div class="kena-info-row"><b>Sanskrit</b><span>${esc(a.sanskrit)}</span></div><div class="kena-info-row"><b>Author</b><span>${esc(a.author)}</span></div><div class="kena-info-row"><b>Religion</b><span>Hinduism</span></div><div class="kena-info-row"><b>Language</b><span>${esc(a.language)}</span></div><div class="kena-info-row"><b>Genre</b><span>${esc(a.genre)}</span></div>${a.rows.map(([k,v])=>`<div class="kena-info-row"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('')}</aside>`;}
  function open(button,name,a){close();button.classList.add('is-active');button.setAttribute('aria-pressed','true');shade=document.createElement('div');shade.className='kena-article-backdrop scripture-wiki-backdrop';reader=document.createElement('section');reader.className='kena-article-reader scripture-wiki-reader itihasa-v5-reader';reader.setAttribute('role','dialog');reader.setAttribute('aria-modal','true');reader.setAttribute('aria-label',`${name} article`);reader.innerHTML=`<header class="kena-article-head"><div><span class="eyebrow">Itihāsa</span><h1>${esc(a.title)}</h1></div><button class="kena-article-close" type="button" aria-label="Close">×</button></header><div class="kena-article-scroll"><article class="scripture-wiki-article itihasa-human-article">${infobox(a)}${a.body()}${notes(a)}</article></div>`;document.body.append(shade,reader);document.documentElement.classList.add('kena-article-open');reader.addEventListener('click',e=>{const c=e.target.closest('.itihasa-cite button,.itihasa-note-link');if(c){e.preventDefault();e.stopPropagation();source(a,Number(c.dataset.note));return;}if(e.target.closest('.kena-article-close'))close();});shade.addEventListener('click',close);return true;}

  if(!document.getElementById('itihasa-v5-style')){const s=document.createElement('style');s.id='itihasa-v5-style';s.textContent=`.itihasa-human-article .kena-lead p{max-width:810px;font-size:16.6px;line-height:1.82}.itihasa-human-article .kena-section>p{max-width:950px;font-size:16px;line-height:1.82}.itihasa-human-article .kena-section h3{max-width:950px;margin:34px 0 10px!important;font-size:21px!important;line-height:1.35}.itihasa-human-article .kena-section h3+ p{margin-top:0}.itihasa-cite{vertical-align:super;margin-left:1px}.itihasa-cite button,.itihasa-note-link{border:0;background:transparent;color:#36c;padding:0 1px;font:600 10.5px/1 Arial,sans-serif;cursor:pointer}.itihasa-cite button:hover,.itihasa-note-link:hover{text-decoration:underline}.itihasa-source-card{position:fixed;z-index:13050;right:22px;bottom:22px;width:min(460px,calc(100vw - 32px));padding:17px 18px 16px;border:1px solid #a2a9b1;border-radius:4px;background:#fff;box-shadow:0 12px 38px rgba(0,0,0,.24);color:#202122;font-family:Arial,sans-serif}.itihasa-source-card strong{display:block;padding-right:30px;font-size:15px;line-height:1.35}.itihasa-source-card p{margin:8px 0 10px;font-size:13.5px;line-height:1.55}.itihasa-source-card a{color:#36c;font-size:13px}.itihasa-source-num{margin-bottom:5px;color:#54595d;font-size:11px;font-weight:700;text-transform:uppercase}.itihasa-source-close{position:absolute;right:8px;top:7px;border:0;background:transparent;font-size:23px;cursor:pointer}.itihasa-human-article .kena-references li{margin-bottom:13px}.itihasa-human-article .kena-references li span{color:#54595d;font-size:12.8px}@media(max-width:700px){.itihasa-source-card{right:12px;bottom:12px;width:calc(100vw - 24px)}.itihasa-human-article .kena-section>p{font-size:15.8px;line-height:1.78}.itihasa-human-article .kena-lead p{font-size:16px;line-height:1.78}}`;document.head.append(s);}

  window.openScriptureEncyclopedia=function(button){const name=button?.dataset?.name||button?.querySelector?.('span')?.textContent?.trim();const kind=button?.dataset?.kind||'';if(kind==='Itihāsa'&&ARTICLES[name])return open(button,name,ARTICLES[name]);return typeof fallbackOpen==='function'?fallbackOpen(button):false;};
